<script setup>
import { ref, computed } from 'vue';
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import OperatorPerusahaanLayout from '@/Layouts/OperatorPerusahaanLayout.vue';
import CountryCodeSelect from '@/Components/CountryCodeSelect.vue';
import { useToast } from '@/Composables/useToast';
import ToastContainer from '@/Components/ToastContainer.vue';
import FormErrorSummary from '@/Components/FormErrorSummary.vue';
import { errorSummary } from '@/Composables/useFormErrorToast';

defineOptions({ layout: OperatorPerusahaanLayout });
const props = defineProps({ customers: Object, filters: Object });
const toast = useToast();

const searchInput = ref(props.filters?.search || '');
const statusFilter = ref(props.filters?.status || '');
const terhapusFilter = ref(props.filters?.terhapus || 'tidak');
const sortField = ref(props.filters?.sort_field || '');
const sortDir = ref(props.filters?.sort_dir || 'asc');
const perPage = ref(props.filters?.per_page && !isNaN(props.filters.per_page) ? Number(props.filters.per_page) : 10);
const perPageOptions = [5, 10, 25, 50, 100];

function buildQuery(o = {}) {
  const p = { ...o };
  if (p.search === undefined) p.search = searchInput.value || undefined;
  if (p.status === undefined) p.status = statusFilter.value || undefined;
  if (p.terhapus === undefined) p.terhapus = terhapusFilter.value || undefined;
  if (p.sort_field === undefined) p.sort_field = sortField.value || undefined;
  if (p.sort_dir === undefined) p.sort_dir = sortDir.value || undefined;
  if (p.per_page === undefined) p.per_page = perPage.value;
  Object.keys(p).forEach(k => { if (p[k] === undefined) delete p[k]; });
  return p;
}
function fetchData(o = {}) { router.get('/operator-perusahaan/customer', buildQuery(o), { preserveState: true, preserveScroll: true, replace: true }); }
function applySearch() { fetchData({ search: searchInput.value || undefined, page: 1 }); }
function clearSearch() { searchInput.value = ''; fetchData({ search: undefined, page: 1 }); }
function applyFilters() { fetchData({ page: 1 }); }
function resetFilters() { searchInput.value = ''; statusFilter.value = ''; terhapusFilter.value = 'tidak'; fetchData({ search: undefined, status: undefined, terhapus: 'tidak', page: 1 }); }

function sort(f) { if (sortField.value === f) { sortDir.value = sortDir.value === 'asc' ? 'desc' : (sortField.value = '', 'asc'); } else { sortField.value = f; sortDir.value = 'asc'; } fetchData({ sort_field: sortField.value || undefined, sort_dir: sortDir.value, page: 1 }); }
function sortIcon(f) { return sortField.value !== f ? 'fa-sort' : (sortDir.value === 'asc' ? 'fa-sort-up' : 'fa-sort-down'); }
function sortOrder(f) { return sortField.value === f ? 1 : null; }

const currentPage = computed(() => props.customers?.current_page || 1);
const totalPages = computed(() => props.customers?.last_page || 1);
function changePerPage(n) { perPage.value = n; fetchData({ per_page: n, page: 1 }); }
function goToPage(p) { fetchData({ page: Math.max(1, Math.min(p, totalPages.value)) }); }
const visiblePages = computed(() => { const pg = []; const t = totalPages.value; const c = currentPage.value; let st = Math.max(1, c - 2); let en = Math.min(t, c + 2); if (en - st < 4) { if (st === 1) en = Math.min(t, st + 4); else st = Math.max(1, en - 4); } for (let i = st; i <= en; i++) pg.push(i); return pg; });

const selectedIds = ref([]); const selectAll = ref(false);
const customersList = computed(() => props.customers?.data || []);
function toggleSelectAll() { selectedIds.value = selectAll.value ? customersList.value.map(c => c.id) : []; }
function toggleSelect(id) { const i = selectedIds.value.indexOf(id); i === -1 ? selectedIds.value.push(id) : selectedIds.value.splice(i, 1); selectAll.value = selectedIds.value.length === customersList.value.length; }

const page = usePage();
const can = (perm) => page.props.permissions?.includes(perm);

function bulkDelete() { if (!selectedIds.value.length) return; router.post('/operator-perusahaan/customer/bulk-delete', { ids: [...selectedIds.value] }, { preserveState: true, preserveScroll: true, onSuccess: () => { selectedIds.value = []; selectAll.value = false; toast.success('Customer berhasil dihapus.'); }, onError: () => toast.error('Gagal menghapus customer.') }); }
function bulkRestore() { if (!selectedIds.value.length) return; router.post('/operator-perusahaan/customer/bulk-restore', { ids: [...selectedIds.value] }, { preserveState: true, preserveScroll: true, onSuccess: () => { selectedIds.value = []; selectAll.value = false; toast.success('Customer berhasil dipulihkan.'); }, onError: () => toast.error('Gagal memulihkan customer.') }); }
function bulkSetStatus(s) { if (!selectedIds.value.length) return; router.post('/operator-perusahaan/customer/bulk-status', { ids: [...selectedIds.value], status: s }, { preserveState: true, preserveScroll: true, onSuccess: () => { selectedIds.value = []; selectAll.value = false; toast.success(`Customer berhasil ${s === 'Aktif' ? 'diaktifkan' : 'dinonaktifkan'}.`); }, onError: () => toast.error('Gagal mengubah status.') }); }
function bulkVerifyEmail() { if (!selectedIds.value.length) return; router.post('/operator-perusahaan/customer/bulk-verify-email', { ids: [...selectedIds.value] }, { preserveState: true, preserveScroll: true, onSuccess: () => { selectedIds.value = []; selectAll.value = false; toast.success('Customer ditandai email verified.'); }, onError: () => toast.error('Gagal menandai email verified.') }); }
function restoreCustomer(c) { router.patch(`/operator-perusahaan/customer/${c.id}/restore`, {}, { preserveState: true, preserveScroll: true, onSuccess: () => toast.success(`Customer "${c.nama}" berhasil dipulihkan.`), onError: () => toast.error('Gagal memulihkan customer.') }); }

function statusBadge(s) { return s === 'Aktif' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'; }
function formatTelepon(c) { return (c.kode_negara || '') + ' ' + (c.no_telp || ''); }

const selectedItem = ref(null);
const editingId = ref(null);
const showCreateModal = ref(false); const showDetailModal = ref(false); const showEditModal = ref(false); const showDeleteModal = ref(false);
const kodeNegaraList = ['+62', '+60', '+65', '+66', '+84', '+1', '+44', '+81', '+86']; // legacy, kept for backwards compat in case some other place uses it
const createForm = useForm({ kode: '', nama: '', email: '', kode_negara: '+62', no_telp: '', no_nik: '', no_kk: '', photo_ktp: null, photo_kk: null, photo_profile: null, alamat: '', status: 'Aktif', password: '' });
const editForm = useForm({ kode: '', nama: '', email: '', kode_negara: '+62', no_telp: '', no_nik: '', no_kk: '', photo_ktp: null, photo_kk: null, photo_profile: null, alamat: '', status: 'Aktif', password: '', email_verified_at_action: null });
const showImportModal = ref(false);
const importForm = useForm({ file: null });

function exportAll() { window.open('/operator-perusahaan/customer/export', '_blank'); }
function exportSelected() { if (!selectedIds.value.length) return; window.open('/operator-perusahaan/customer/export?ids=' + selectedIds.value.join(','), '_blank'); }
function downloadTemplate() { window.open('/operator-perusahaan/customer/template', '_blank'); }
function openImport() { importForm.reset(); importForm.clearErrors(); showImportModal.value = true; }
function submitImport() { importForm.post('/operator-perusahaan/customer/import', { preserveState: true, preserveScroll: true, onSuccess: () => { showImportModal.value = false; fetchData(); toast.success('Import berhasil.'); }, onError: () => toast.error('Import gagal: ' + errorSummary(importForm.errors), 6000) }); }

const showCreatePw = ref(false);
const showEditPw = ref(false);
function openCreate() { createForm.reset(); createForm.clearErrors(); showCreateModal.value = true; }
function openDetail(c) { selectedItem.value = c; showDetailModal.value = true; }
function openEdit(c) { editingId.value = c.id; editForm.reset(); editForm.clearErrors(); editForm.kode = c.kode || ''; editForm.nama = c.nama; editForm.email = c.email; editForm.kode_negara = c.kode_negara; editForm.no_telp = c.no_telp; editForm.no_nik = c.no_nik; editForm.no_kk = c.no_kk; editForm.photo_ktp = null; editForm.photo_kk = null; editForm.photo_profile = null; editForm.alamat = c.alamat; editForm.status = c.status; editForm.password = ''; editForm.email_verified_at_action = null; showEditModal.value = true; }
function openDelete(c) { selectedItem.value = c; showDeleteModal.value = true; }
function saveCreate() {
    createForm
        .transform(data => {
            const cleaned = { ...data };
            if (!(cleaned.photo_ktp instanceof File)) delete cleaned.photo_ktp;
            if (!(cleaned.photo_kk instanceof File)) delete cleaned.photo_kk;
            if (!(cleaned.photo_profile instanceof File)) delete cleaned.photo_profile;
            return cleaned;
        })
        .post('/operator-perusahaan/customer', { preserveState: true, preserveScroll: true, onSuccess: () => { showCreateModal.value = false; toast.success('Customer berhasil ditambahkan.'); }, onError: () => toast.error('Validasi gagal: ' + errorSummary(createForm.errors), 6000) });
}
function saveEdit() {
    editForm
        .transform(data => {
            const cleaned = { ...data };
            if (!(cleaned.photo_ktp instanceof File)) delete cleaned.photo_ktp;
            if (!(cleaned.photo_kk instanceof File)) delete cleaned.photo_kk;
            if (!(cleaned.photo_profile instanceof File)) delete cleaned.photo_profile;
            cleaned._method = 'PUT';
            return cleaned;
        })
        .post(`/operator-perusahaan/customer/${editingId.value}`, { preserveState: true, preserveScroll: true, onSuccess: () => { showEditModal.value = false; toast.success('Customer berhasil diperbarui.'); }, onError: () => toast.error('Validasi gagal: ' + errorSummary(editForm.errors), 6000) });
}
function confirmDelete() { const name = selectedItem.value?.nama; router.delete(`/operator-perusahaan/customer/${selectedItem.value?.id}`, { preserveState: true, preserveScroll: true, onSuccess: () => { showDeleteModal.value = false; toast.success(`Customer "${name}" berhasil dihapus.`); if (customersList.value.length === 0 && currentPage.value > 1) goToPage(currentPage.value - 1); }, onError: () => toast.error('Gagal menghapus customer.') }); }
</script>

<template>
  <div>
    <Head title="Customer | Operator Perusahaan" />
    <ToastContainer />
    <div class="space-y-6">
      <nav class="flex items-center gap-1.5 text-sm"><Link href="/operator-perusahaan/dashboard" class="text-gray-500 dark:text-gray-400 hover:text-sky-600 dark:hover:text-sky-400 transition-colors"><i class="fas fa-home"></i></Link><i class="fas fa-chevron-right text-[10px] text-gray-400 dark:text-gray-500"></i><Link href="/operator-perusahaan/dashboard" class="text-gray-500 dark:text-gray-400 hover:text-sky-600 dark:hover:text-sky-400 transition-colors">Dashboard</Link><i class="fas fa-chevron-right text-[10px] text-gray-400 dark:text-gray-500"></i><span class="text-gray-900 dark:text-white font-medium">Customer</span></nav>
      <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3"><div><h2 class="text-xl sm:text-2xl font-bold text-gray-900 dark:text-white">Customer</h2><p class="text-xs sm:text-sm text-gray-500 dark:text-gray-400 mt-0.5">Kelola data pelanggan internet Anda.</p></div><div class="flex flex-col sm:flex-row items-stretch sm:items-center gap-2"><button v-if="can('customer.create') && terhapusFilter !== 'ya'" @click="openCreate" class="inline-flex items-center justify-center px-4 py-2 bg-sky-600 text-white text-sm font-medium rounded-lg hover:bg-sky-700 transition-colors shadow-sm whitespace-nowrap w-full sm:w-auto" data-testid="btn-tambah"><i class="fas fa-plus mr-1.5"></i> Tambah Customer</button><button v-if="can('customer.import')" @click="openImport" class="inline-flex items-center justify-center px-4 py-2 bg-emerald-600 text-white text-sm font-medium rounded-lg hover:bg-emerald-700 transition-colors shadow-sm whitespace-nowrap w-full sm:w-auto" data-testid="btn-import"><i class="fas fa-upload mr-1.5"></i> Import</button><button v-if="can('customer.export')" @click="exportAll" class="inline-flex items-center justify-center px-4 py-2 bg-violet-600 text-white text-sm font-medium rounded-lg hover:bg-violet-700 transition-colors shadow-sm whitespace-nowrap w-full sm:w-auto" data-testid="btn-export"><i class="fas fa-download mr-1.5"></i> Export</button><a v-if="can('customer.import')" @click="downloadTemplate" class="inline-flex items-center justify-center px-3 py-2 text-xs text-sky-600 dark:text-sky-400 hover:underline cursor-pointer whitespace-nowrap w-full sm:w-auto text-center"><i class="fas fa-file-excel mr-1"></i> Template</a></div></div>
      <div class="flex flex-col sm:flex-row gap-3 items-start sm:items-center justify-between"><div class="relative w-full sm:w-72"><div class="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none"><i class="fas fa-search text-gray-400 text-sm"></i></div><input v-model="searchInput" type="text" placeholder="Cari customer..." class="w-full pl-10 pr-16 py-2.5 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white text-sm focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none transition-colors" @keydown.enter="applySearch" data-testid="input-search"><div class="absolute inset-y-0 right-0 flex items-center gap-1 pr-1.5"><button v-if="searchInput" @click="clearSearch" class="p-1 rounded text-gray-400 hover:text-gray-600 dark:hover:text-white transition-colors" title="Clear"><i class="fas fa-times text-xs"></i></button><button @click="applySearch" class="px-2 py-1 rounded bg-sky-600 text-white hover:bg-sky-700 transition-colors" title="Cari"><i class="fas fa-search text-xs"></i></button></div></div><div class="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400"><span>{{ props.customers?.total || 0 }} data</span><button v-if="statusFilter || terhapusFilter !== 'tidak' || searchInput" @click="resetFilters" class="text-xs text-red-500 hover:text-red-700 dark:hover:text-red-400 underline">Reset filter</button></div></div>

      <!-- Filter Card -->
      <div class="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-4 shadow-sm"><div class="flex flex-wrap items-end gap-4"><div class="min-w-[160px]"><label class="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1.5 uppercase tracking-wider">Status</label><select v-model="statusFilter" class="w-full px-3 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-900 text-gray-900 dark:text-white text-sm focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none transition-colors"><option value="">Semua</option><option value="Aktif">Ya (Aktif)</option><option value="Nonaktif">Tidak (Nonaktif)</option></select></div><div class="min-w-[160px]"><label class="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1.5 uppercase tracking-wider">Terhapus</label><select v-model="terhapusFilter" class="w-full px-3 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-900 text-gray-900 dark:text-white text-sm focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none transition-colors"><option value="tidak">Tidak</option><option value="ya">Ya</option></select></div><button @click="applyFilters" class="px-4 py-2 bg-sky-600 text-white text-sm font-medium rounded-lg hover:bg-sky-700 transition-colors shadow-sm"><i class="fas fa-filter mr-1.5"></i>Filter</button></div></div>

      <!-- Bulk Action Bar -->
      <div v-if="selectedIds.length > 0" class="flex items-center justify-between px-4 py-3 bg-sky-50 dark:bg-sky-900/20 border border-sky-200 dark:border-sky-800 rounded-xl shadow-sm"><span class="text-sm font-medium text-sky-700 dark:text-sky-300"><i class="fas fa-check-circle mr-1.5"></i> {{ selectedIds.length }} data dipilih</span><div class="flex items-center gap-2"><button v-if="can('customer.restore') && terhapusFilter === 'ya'" @click="bulkRestore()" class="px-3 py-1.5 text-xs font-medium rounded-lg bg-emerald-600 text-white hover:bg-emerald-700 transition-colors"><i class="fas fa-undo-alt mr-1"></i> Pulihkan</button><button v-if="can('customer.edit') && terhapusFilter !== 'ya'" @click="bulkSetStatus('Aktif')" class="px-3 py-1.5 text-xs font-medium rounded-lg bg-emerald-600 text-white hover:bg-emerald-700 transition-colors"><i class="fas fa-check mr-1"></i> Aktifkan</button><button v-if="can('customer.edit') && terhapusFilter !== 'ya'" @click="bulkSetStatus('Nonaktif')" class="px-3 py-1.5 text-xs font-medium rounded-lg bg-amber-600 text-white hover:bg-amber-700 transition-colors"><i class="fas fa-ban mr-1"></i> Nonaktifkan</button><button v-if="can('customer.verify-email') && terhapusFilter !== 'ya'" @click="bulkVerifyEmail()" class="px-3 py-1.5 text-xs font-medium rounded-lg bg-emerald-600 text-white hover:bg-emerald-700 transition-colors"><i class="fas fa-envelope-circle-check mr-1"></i> Tandai Verified</button><button v-if="can('customer.delete')" @click="bulkDelete()" class="px-3 py-1.5 text-xs font-medium rounded-lg bg-red-600 text-white hover:bg-red-700 transition-colors"><i class="fas fa-trash-alt mr-1"></i> Hapus</button><button v-if="can('customer.export')" @click="exportSelected" class="px-3 py-1.5 text-xs font-medium rounded-lg bg-violet-600 text-white hover:bg-violet-700 transition-colors"><i class="fas fa-download mr-1"></i> Export Selected</button></div></div>

      <!-- Table -->
      <div class="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden"><div class="overflow-x-auto"><table data-testid="table-data" class="w-full text-sm min-w-[800px]"><thead class="bg-gray-50 dark:bg-gray-900 border-b border-gray-200 dark:border-gray-700"><tr><th class="px-4 py-3 w-10"><input v-model="selectAll" type="checkbox" @change="toggleSelectAll" class="rounded border-gray-300 dark:border-gray-600 text-sky-600 focus:ring-sky-500" data-testid="checkbox-select-all" /></th><th @click="sort('code')" class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400 cursor-pointer select-none hover:text-gray-900 dark:hover:text-white transition-colors"><span class="inline-flex items-center gap-1">Kode <span v-if="sortOrder('code')" class="inline-flex items-center gap-0.5 text-sky-500 dark:text-sky-400"><i :class="['fas', sortIcon('code'), 'text-[10px]']"></i><span class="text-[10px] font-bold leading-none">{{ sortOrder('code') }}</span></span><i v-else class="fas fa-sort text-[10px] text-gray-400 dark:text-gray-500"></i></span></th><th @click="sort('name')" class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400 cursor-pointer select-none hover:text-gray-900 dark:hover:text-white transition-colors"><span class="inline-flex items-center gap-1">Nama <span v-if="sortOrder('name')" class="inline-flex items-center gap-0.5 text-sky-500 dark:text-sky-400"><i :class="['fas', sortIcon('name'), 'text-[10px]']"></i><span class="text-[10px] font-bold leading-none">{{ sortOrder('name') }}</span></span><i v-else class="fas fa-sort text-[10px] text-gray-400 dark:text-gray-500"></i></span></th><th @click="sort('email')" class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400 cursor-pointer select-none hover:text-gray-900 dark:hover:text-white transition-colors"><span class="inline-flex items-center gap-1">Email <span v-if="sortOrder('email')" class="inline-flex items-center gap-0.5 text-sky-500 dark:text-sky-400"><i :class="['fas', sortIcon('email'), 'text-[10px]']"></i><span class="text-[10px] font-bold leading-none">{{ sortOrder('email') }}</span></span><i v-else class="fas fa-sort text-[10px] text-gray-400 dark:text-gray-500"></i></span></th><th class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400">Email Verified</th><th class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400">Telepon</th><th class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400">Alamat</th><th @click="sort('is_active')" class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400 cursor-pointer select-none hover:text-gray-900 dark:hover:text-white transition-colors"><span class="inline-flex items-center gap-1">Status <span v-if="sortOrder('is_active')" class="inline-flex items-center gap-0.5 text-sky-500 dark:text-sky-400"><i :class="['fas', sortIcon('is_active'), 'text-[10px]']"></i><span class="text-[10px] font-bold leading-none">{{ sortOrder('is_active') }}</span></span><i v-else class="fas fa-sort text-[10px] text-gray-400 dark:text-gray-500"></i></span></th><th class="px-4 py-3 text-right font-semibold text-gray-600 dark:text-gray-400 w-32">Aksi</th></tr></thead><tbody class="divide-y divide-gray-200 dark:divide-gray-700"><tr v-if="customersList.length === 0"><td colspan="9" class="px-4 py-16 text-center text-gray-500 dark:text-gray-400"><i class="fas fa-users text-3xl mb-2 block opacity-40"></i>Tidak ada data customer.</td></tr><tr v-for="c in customersList" :key="c.id" :class="['transition-colors', c.dihapus ? 'bg-red-50/30 dark:bg-red-900/10 opacity-60' : 'hover:bg-gray-50 dark:hover:bg-gray-700/30']"><td class="px-4 py-3"><input :checked="selectedIds.includes(c.id)" type="checkbox" @change="toggleSelect(c.id)" class="rounded border-gray-300 dark:border-gray-600 text-sky-600 focus:ring-sky-500" /></td><td class="px-4 py-3"><span class="font-mono text-xs text-gray-500 dark:text-gray-400 whitespace-nowrap" :class="{ 'line-through': c.dihapus }">{{ c.kode || '-' }}</span></td><td class="px-4 py-3"><div class="flex items-center gap-2.5"><div class="w-8 h-8 rounded-full bg-gradient-to-br from-sky-500 to-blue-600 flex items-center justify-center text-white text-xs font-bold shrink-0">{{ c.nama.charAt(0) }}</div><span class="font-medium text-gray-900 dark:text-white whitespace-nowrap" :class="{ 'line-through': c.dihapus }">{{ c.nama }}</span></div></td><td class="px-4 py-3 text-gray-600 dark:text-gray-400 whitespace-nowrap" :class="{ 'line-through': c.dihapus }">{{ c.email }}</td><td class="px-4 py-3 whitespace-nowrap"><span v-if="c.email_verified" class="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400" :title="c.email_verified_at ? 'Verified pada ' + c.email_verified_at : 'Verified'"><i class="fas fa-check-circle mr-1"></i> Verified</span><span v-else class="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400" title="Email belum diverifikasi"><i class="fas fa-clock mr-1"></i> Belum</span></td><td class="px-4 py-3 text-gray-600 dark:text-gray-400 whitespace-nowrap" :class="{ 'line-through': c.dihapus }">{{ formatTelepon(c) }}</td><td class="px-4 py-3 text-gray-600 dark:text-gray-400 max-w-[180px] truncate" :class="{ 'line-through': c.dihapus }">{{ c.alamat || '-' }}</td><td class="px-4 py-3 whitespace-nowrap"><span v-if="c.dihapus" class="inline-flex px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400">Terhapus</span><span v-else :class="['inline-flex px-2.5 py-0.5 rounded-full text-xs font-medium', statusBadge(c.status)]">{{ c.status }}</span></td><td class="px-4 py-3 whitespace-nowrap"><div class="flex items-center justify-end gap-1"><button v-if="can('customer.detail')" @click="openDetail(c)" class="p-2 rounded-lg text-g